//! MXMACA (MetaX C500) native Wave64 matrix operations.
//!
//! These are NOT generated by `cuda-intrinsics-gen`: they are a MetaX
//! extension restored from the pre-generation `ops/wmma.rs`. The wave width
//! (64), tile shape (16x16x16), and per-lane fragment ABI differ from CUDA's
//! `m16n8k16` operations, so they use dedicated op names under `nvvm.*`.

use pliron::{
    builtin::op_interfaces::{NOpdsInterface, NResultsInterface},
    context::Context,
    context::Ptr,
    op::Op,
    operation::Operation,
};
use pliron_derive::pliron_op;

/// C500-native Wave64 MMA: m16n16k16 with f32 accumulator and f16 inputs.
///
/// Operands are C[0..4] f32, A[0..2] packed i32, then B[0..2] packed i32.
/// Results are four f32 accumulator registers.
#[pliron_op(
    name = "nvvm.mma_m16n16k16_f32_f16",
    format,
    verifier = "succ",
    interfaces = [NOpdsInterface<8>, NResultsInterface<4>],
)]
pub struct MmaM16N16K16F32F16Op;

impl MmaM16N16K16F32F16Op {
    /// Wrap an existing operation pointer.
    pub fn new(op: Ptr<Operation>) -> Self {
        MmaM16N16K16F32F16Op { op }
    }
}

/// C500-native Wave64 MMA: m16n16k16 with f32 accumulator and bf16 inputs.
#[pliron_op(
    name = "nvvm.mma_m16n16k16_f32_bf16",
    format,
    verifier = "succ",
    interfaces = [NOpdsInterface<8>, NResultsInterface<4>],
)]
pub struct MmaM16N16K16F32Bf16Op;

impl MmaM16N16K16F32Bf16Op {
    /// Wrap an existing operation pointer.
    pub fn new(op: Ptr<Operation>) -> Self {
        Self { op }
    }
}

/// C500-native Wave64 MMA: m16n16k16 with i32 accumulator and i8 inputs.
#[pliron_op(
    name = "nvvm.mma_m16n16k16_i32_i8",
    format,
    verifier = "succ",
    interfaces = [NOpdsInterface<6>, NResultsInterface<4>],
)]
pub struct MmaM16N16K16I32I8Op;

impl MmaM16N16K16I32I8Op {
    /// Wrap an existing operation pointer.
    pub fn new(op: Ptr<Operation>) -> Self {
        Self { op }
    }
}

/// Register the MXMACA native MMA operations with the context.
pub(super) fn register(ctx: &mut Context) {
    MmaM16N16K16F32F16Op::register(ctx);
    MmaM16N16K16F32Bf16Op::register(ctx);
    MmaM16N16K16I32I8Op::register(ctx);
}
